//! The `OpenBot` marketplace content Codync ships with: agents, skills and app listings.
//!
//! The files under `openbot/` are generated by `tools/import-openbot-catalog.mjs` from the `OpenBot`
//! marketplace (see `openbot/NOTICE.md`). Browsing is offline, so the marketplace works on a computer
//! that has never reached GitHub. Skills install from the embedded archive.

use anyhow::{Context, Result, anyhow, bail};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::sync::LazyLock;

/// `Skill::source` prefix of a skill shipped in this catalog.
pub const SOURCE: &str = "openbot/";

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Routine {
    pub name: String,
    pub instruction: String,
    pub active: bool,
    pub schedule: Value,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Agent {
    pub id: String,
    pub name: String,
    /// The one job and its named result, under the name.
    pub title: String,
    pub instructions: String,
    pub category: String,
    pub creator: String,
    pub version: u32,
    /// The date the catalog last changed it, YYYY-MM-DD (empty in older catalogs).
    #[serde(default)]
    pub updated: String,
    pub avatar_color: String,
    pub avatar_shape: String,
    pub featured: bool,
    pub skills: Vec<String>,
    pub routines: Vec<Routine>,
}

impl Agent {
    /// What a card shows.
    pub fn public(&self, installed: bool) -> Value {
        json!({
            "id": self.id, "name": self.name, "title": self.title, "category": self.category,
            "creator": self.creator, "version": self.version, "updated": self.updated,
            "avatarColor": self.avatar_color, "avatarShape": self.avatar_shape,
            "featured": self.featured, "installed": installed,
        })
    }
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct CatalogSkill {
    pub id: String,
    pub name: String,
    pub description: String,
    pub category: String,
    /// The upstream source, such as `openbot`, `openai` or `pstack`.
    pub source: String,
    pub featured: bool,
    #[serde(default)]
    pub pack: Option<String>,
    /// The `SKILL.md` body without its front matter.
    pub body: String,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Pack {
    pub id: String,
    pub name: String,
    pub description: String,
    pub category: String,
    pub children: Vec<String>,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct App {
    pub id: String,
    pub name: String,
    pub tagline: String,
    pub description: String,
    pub category: String,
    pub creator: String,
    pub version: String,
    /// The date the catalog last changed it, YYYY-MM-DD (empty in older catalogs).
    #[serde(default)]
    pub updated: String,
    #[serde(default)]
    pub icon: Option<String>,
    #[serde(default)]
    pub website: Option<String>,
    pub featured: bool,
    /// `link` (browser sign-in), `open` (nothing), `key` (fields) or `local` (steps).
    pub setup: String,
    pub server: Server,
    #[serde(default)]
    pub fields: Vec<Field>,
    #[serde(default)]
    pub steps: Vec<String>,
    #[serde(default)]
    pub docs_url: Option<String>,
    #[serde(default)]
    pub docs_label: Option<String>,
    #[serde(default)]
    pub prompts: Vec<Prompt>,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Server {
    pub name: String,
    pub transport: String,
    #[serde(default)]
    pub url: Option<String>,
    #[serde(default)]
    pub command: Option<String>,
    #[serde(default)]
    pub args: Vec<String>,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct Field {
    pub id: String,
    pub label: String,
    #[serde(default)]
    pub env: Option<String>,
    #[serde(default)]
    pub header: Option<String>,
    #[serde(default)]
    pub url: bool,
    #[serde(default)]
    pub placeholder: Option<String>,
    #[serde(default)]
    pub hint: Option<String>,
    pub required: bool,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Prompt {
    pub id: String,
    pub text: String,
}

#[derive(Deserialize)]
struct Agents {
    agents: Vec<Agent>,
}

#[derive(Deserialize)]
struct Skills {
    skills: Vec<CatalogSkill>,
    packs: Vec<Pack>,
}

#[derive(Deserialize)]
struct Apps {
    apps: Vec<App>,
}

static AGENTS: LazyLock<Agents> =
    LazyLock::new(|| serde_json::from_str(include_str!("openbot/agents.json")).expect("valid agent catalog"));
static SKILLS: LazyLock<Skills> =
    LazyLock::new(|| serde_json::from_str(include_str!("openbot/skills.json")).expect("valid skill catalog"));
static APPS: LazyLock<Apps> =
    LazyLock::new(|| serde_json::from_str(include_str!("openbot/apps.json")).expect("valid app catalog"));
/// Every skill folder, for installing without a network.
static ARCHIVE: &[u8] = include_bytes!("openbot/skills.tar.gz");

pub fn agents() -> &'static [Agent] {
    &AGENTS.agents
}

pub fn agent(id: &str) -> Result<&'static Agent> {
    AGENTS.agents.iter().find(|a| a.id == id).ok_or_else(|| anyhow!("Unknown agent"))
}

pub fn skills() -> &'static [CatalogSkill] {
    &SKILLS.skills
}

pub fn skill(id: &str) -> Option<&'static CatalogSkill> {
    SKILLS.skills.iter().find(|s| s.id == id)
}

pub fn pack(id: &str) -> Option<&'static Pack> {
    SKILLS.packs.iter().find(|p| p.id == id)
}

pub fn apps() -> &'static [App] {
    &APPS.apps
}

/// The catalog agents `search` and `category` keep, with whether the computer has each one.
pub fn browse_agents(installed: &[String], search: &str, category: &str) -> Vec<Value> {
    let query = search.trim().to_lowercase();
    agents()
        .iter()
        .filter(|a| {
            (category.is_empty() || a.category == category)
                && (query.is_empty()
                    || a.name.to_lowercase().contains(&query)
                    || a.title.to_lowercase().contains(&query))
        })
        .map(|a| a.public(installed.contains(&a.id)))
        .collect()
}

/// An agent's page: its instructions, and each skill with what it is for.
pub fn agent_details(id: &str, installed: bool) -> Result<Value> {
    let a = agent(id)?;
    let mut page = a.public(installed);
    let skills: Vec<Value> = a
        .skills
        .iter()
        .map(|id| match pack(id) {
            Some(p) => json!({"id": p.id, "name": p.name, "description": p.description, "pack": true}),
            None => match skill(id) {
                Some(s) => json!({"id": s.id, "name": s.name, "description": s.description, "pack": false}),
                None => json!({"id": id, "name": id, "description": "", "pack": false}),
            },
        })
        .collect();
    page["instructions"] = json!(a.instructions);
    page["skills"] = json!(skills);
    page["routines"] = json!(a.routines);
    Ok(page)
}

/// What a skill card shows. `installed` says whether its folder exists already.
pub fn skill_public(s: &CatalogSkill, installed: bool) -> Value {
    json!({
        "source": format!("{SOURCE}{}", s.id), "name": s.name, "description": s.description,
        "category": s.category, "creator": s.source, "featured": s.featured,
        "pack": s.pack, "installed": installed,
    })
}

/// The catalog skills, featured first, marked installed.
pub fn browse_skills(installed: &[String]) -> Vec<Value> {
    let mut list: Vec<&CatalogSkill> = skills().iter().collect();
    list.sort_by_key(|s| !s.featured);
    list.into_iter().map(|s| skill_public(s, installed.contains(&format!("{SOURCE}{}", s.id)))).collect()
}

/// A bundled skill's instructions by `openbot/<id>`, or a pack's description and its skills.
pub fn skill_details(source: &str) -> Result<Value> {
    let id = source.strip_prefix(SOURCE).ok_or_else(|| anyhow!("Unknown skill"))?;
    if let Some(p) = pack(id) {
        let children: Vec<Value> =
            p.children.iter().filter_map(|id| skill(id)).map(|s| json!({"id": s.id, "name": s.name})).collect();
        return Ok(json!({"markdown": p.description, "skills": children}));
    }
    let s = skill(id).ok_or_else(|| anyhow!("Unknown skill"))?;
    Ok(json!({"markdown": s.body}))
}

/// Installs a bundled skill's folder. Returns its id; an installed one stays as it is.
pub fn install(store: &crate::store::Store, source: &str) -> Result<crate::market::Skill> {
    let id = source.strip_prefix(SOURCE).ok_or_else(|| anyhow!("Unknown skill"))?;
    install_id(store, id)
}

/// A skill bundle an agent brings: a pack installs every skill in it.
pub fn ensure(store: &crate::store::Store, id: &str) -> Result<Vec<String>> {
    match pack(id) {
        Some(p) => p.children.iter().map(|id| install_id(store, id).map(|s| s.id)).collect(),
        None => match skill(id) {
            Some(_) => Ok(vec![install_id(store, id)?.id]),
            None => Ok(vec![]),
        },
    }
}

fn install_id(store: &crate::store::Store, id: &str) -> Result<crate::market::Skill> {
    let catalog = skill(id).ok_or_else(|| anyhow!("Unknown skill"))?;
    if let Some(s) = super::reserve_bundled(store, id)? {
        return Ok(s);
    }
    let dest = std::path::PathBuf::from(super::skills_root()).join(&catalog.id);
    extract(&catalog.id, &dest).with_context(|| format!("installing {}", catalog.name))?;
    super::record_bundled(store, &catalog.id, &catalog.name, &catalog.description)
}

/// Writes the archive's `<id>/` entries under `dest`.
fn extract(id: &str, dest: &std::path::Path) -> Result<()> {
    let decoder = flate2::read::GzDecoder::new(ARCHIVE);
    let mut archive = tar::Archive::new(decoder);
    std::fs::create_dir_all(dest)?;
    let prefix = format!("skills/{id}/");
    let mut found = false;
    for entry in archive.entries()? {
        let mut entry = entry?;
        let path = entry.path()?.to_string_lossy().into_owned();
        let Some(rest) = path.strip_prefix(&prefix) else { continue };
        if rest.is_empty() || rest.contains("..") {
            continue;
        }
        found = true;
        let target = dest.join(rest);
        if let Some(parent) = target.parent() {
            std::fs::create_dir_all(parent)?;
        }
        entry.unpack(&target)?;
    }
    if !found {
        bail!("the skill folder is missing");
    }
    Ok(())
}

/// An app's public fields, `installed` when a connector holds it.
pub fn app_public(a: &App, installed: bool) -> Value {
    json!({
        "id": a.id, "name": a.name, "tagline": a.tagline, "description": a.description,
        "category": a.category, "creator": a.creator, "version": a.version, "updated": a.updated, "icon": a.icon,
        "website": a.website, "featured": a.featured, "setup": a.setup, "server": a.server,
        "fields": a.fields, "steps": a.steps, "docsUrl": a.docs_url, "docsLabel": a.docs_label,
        "prompts": a.prompts, "installed": installed,
    })
}

/// The catalog apps `search` keeps, marked installed by their connector.
pub fn browse_apps(installed: &[String], search: &str) -> Vec<Value> {
    let query = search.trim().to_lowercase();
    apps()
        .iter()
        .filter(|a| {
            query.is_empty() || a.name.to_lowercase().contains(&query) || a.tagline.to_lowercase().contains(&query)
        })
        .map(|a| app_public(a, installed.contains(&a.id)))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_catalogs_are_complete_and_unique() {
        let mut ids: Vec<&str> = agents().iter().map(|a| a.id.as_str()).collect();
        let count = ids.len();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), count, "agent ids are unique");
        assert!(agents().iter().any(|a| a.featured));

        let mut ids: Vec<&str> = skills().iter().map(|s| s.id.as_str()).collect();
        let count = ids.len();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), count, "skill ids are unique");
        assert_eq!(apps().len(), apps().iter().map(|a| &a.id).collect::<std::collections::HashSet<_>>().len());
    }

    #[test]
    fn every_agent_skill_resolves() {
        for a in agents() {
            assert!(!a.name.trim().is_empty() && !a.instructions.trim().is_empty(), "{}", a.id);
            for id in &a.skills {
                assert!(skill(id).is_some() || pack(id).is_some(), "{} names {}", a.id, id);
            }
            for r in &a.routines {
                assert!(!r.instruction.trim().is_empty(), "{} routine", a.id);
            }
        }
        for p in &SKILLS.packs {
            for id in &p.children {
                assert!(skill(id).is_some(), "pack {} names {}", p.id, id);
            }
        }
    }

    #[test]
    fn an_app_has_a_server_and_its_setup_fields() {
        for a in apps() {
            assert!(!a.name.trim().is_empty(), "{}", a.id);
            match a.setup.as_str() {
                "open" | "link" => assert!(a.server.url.is_some() || a.server.command.is_some(), "{}", a.id),
                "key" => assert!(
                    !a.fields.is_empty() && a.fields.iter().any(|f| f.env.is_some() || f.header.is_some() || f.url),
                    "{}",
                    a.id
                ),
                "local" => assert!(!a.steps.is_empty(), "{}", a.id),
                other => panic!("{} has the unknown setup {other}", a.id),
            }
        }
    }

    #[test]
    fn the_archive_holds_the_skill_bodies() {
        let id = skills().first().expect("a skill").id.clone();
        let dest = std::env::temp_dir().join(format!("codync-skill-{id}"));
        let _ = std::fs::remove_dir_all(&dest);
        extract(&id, &dest).expect("extracted");
        let md = std::fs::read_to_string(dest.join("SKILL.md")).expect("SKILL.md");
        assert!(md.contains("---"));
        let _ = std::fs::remove_dir_all(&dest);
    }
}
